counterexample:
-- Insert a PERSON row with PERSONID = 12
INSERT INTO PERSON (PERSONID, FIRSTNAME, LASTNAME) VALUES (12, 'Alice', 'Smith');

-- Insert a PERSON row with PERSONID = 1 to satisfy the foreign key in ADDRESS (if needed for other tests)
INSERT INTO PERSON (PERSONID, FIRSTNAME, LASTNAME) VALUES (1, 'Bob', 'Jones');

-- Insert an ADDRESS row with PERSONID = 1
INSERT INTO ADDRESS (ADDRESSID, PERSONID, CITY, STATE) VALUES (1, 1, 'Springfield', 'IL');

-- In Q1, the row from PERSON with PERSONID = 12 won’t join to any ADDRESS row (since 12 <> 1) and the ADDRESS columns will be NULL.
-- In Q2, if the system implicitly casts the numbers to strings and uses LIKE as pattern matching, '12' LIKE '1' might return true (if mistakenly interpreted as a leading‐substring match), causing an erroneous join.

